set -euo pipefail

PLUGIN_ROOT="${CLAUDE_PLUGIN_ROOT:-$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)}"
SKILL_FILE="${PLUGIN_ROOT}/../../skills/dysflow-arnes/SKILL.md"

# 1. Surface the first-call reminders so the agent always sees them.
