else
    echo "[dysflow-plugin] dysflow CLI not on PATH (install: npm i -g dysflow)"
fi

# 3. Worktree detection — if cwd is a git worktree without .dysflow/, nudge.
#    Catches the worktree-bootstrap friction at session start.
