        echo "[dysflow-plugin] WARNING: cwd is a git worktree without .dysflow/."
        echo "  Bootstrap:  dysflow setup --cwd $(pwd) --apply --access-path <path>"
        echo "  See:        skills/dysflow-usage/references/worktrees-and-destinations.md"
